{
  "iteration": 1,
  "pcvs": [
    {
      "name": "penalties_enabled",
      "expression": "int(not sampling_metadata.no_penalties)",
      "rationale": "Captures the fixed overhead of entering the penalty implementation."
    },
    {
      "name": "penalty_logits_elements",
      "expression": "logits.numel() if not sampling_metadata.no_penalties else 0",
      "rationale": "Models dense vocabulary operations and per-request penalty processing."
    },
    {
      "name": "penalty_prompt_elements",
      "expression": "sampling_metadata.prompt_token_ids.numel() if not sampling_metadata.no_penalties else 0",
      "rationale": "Models scanning and counting the padded prompt tokens."
    },
    {
      "name": "penalty_output_tokens",
      "expression": "sum(map(len, sampling_metadata.output_token_ids)) if not sampling_metadata.no_penalties else 0",
      "rationale": "Models conversion and counting of generated token histories using cheap list cardinalities."
    }
  ],
  "hypothesis": "Penalty execution dominates variation in this workload. Its cost combines fixed invocation overhead, dense batch-by-vocabulary operations, prompt-token processing, and generated-history conversion."
}
